{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-838784d41ff360d8","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t  6. Epic-size overage triggers (summary-side): a decomposition summary that\n28\t     acknowledges an epic kept above the ~2-week guideline must record a\n29\t     concrete re-split trigger somewhere in the summary — a bare\n30\t     \"flagged for planning awareness only\" note is an unresolved defect.\n31\t  7. On-matrix bundling record (summary-side): when the summary acknowledges a\n32\t     lower-priority HLR bundled into a higher-priority epic, the HLR\n33\t     Traceability Matrix row itself must carry the `bundled` flag with its\n34\t     rationale — a rationale that lives only in prose outside the matrix reads\n35\t     as an unanalyzed priority collapse.\n36\t\n37\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n38\t\n39\tUsage:\n40\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n41\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n42\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n43\t\"\"\"\n44\t\n45\timport argparse\n46\timport os\n47\timport re\n48\timport sys\n49\t\n50\timport yaml\n51\t\n52\tSECTIONS = [(\"Description\", (\"description\",)),\n53\t            (\"Scope\", (\"scope\",)),\n54\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n55\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n56\t\n57\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n58\t\n59\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n60\t           \"repo-onboarding\")\n61\t\n62\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n63\t# way) — parity with the implementation_type_rules judge.\n64\tPARALLEL_PAIRS = {\n65\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n66\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n67\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n68\t}\n69\t\n70\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n71\t\n72\t# ─── check 6: epic-size overage triggers (summary-side) ───────────────────────\n73\t# A segment \"acknowledges a kept overage\" when it says the work sits above the\n74\t# size guideline. Negations (\"stays within the guideline\") never acknowledge.\n75\tOVERAGE_ACK = re.compile(\n76\t    r'\\b(?:above|exceeds?|exceeded|over|beyond|larger than|'\n77\t    r'at (?:or )?(?:slightly )?above|at the upper (?:end|bound) of)\\s*'\n78\t    r'[^.\\n]{0,80}?\\b(?:guideline|2-week|two-week|one[- ]sprint|'\n79\t    r'epic[- ]size|size guideline)\\b', re.I)\n80\tOVERAGE_NEG = re.compile(\n81\t    r'\\b(?:within|stays? within|does not exceed|no epic (?:exceeds|is above)|'\n82\t    r'under)\\s*[^.\\n]{0,60}?\\b(?:guideline|2-week|size)\\b', re.I)\n83\t# A re-split trigger is a conditional planning statement naming when to split.\n84\tRESPLIT_TRIG = re.compile(\n85\t    r'\\bre-?split\\b|'\n86\t    r'\\bsplit\\b[^.\\n]{0,120}\\bif\\b|'\n87\t    r'\\bif\\b[^.\\n]{0,120}\\b(?:outgrows|exceeds the|finds (?:materially )?more|'\n88\t    r'grows beyond|expands beyond)\\b', re.I)\n89\t\n90\t# ─── check 7: on-matrix bundling record (summary-side) ────────────────────────\n91\t# Fires only when the summary itself acknowledges a bundling DECISION (the\n92\t# word \"bundled\" near an HLR id or a P0/P1/P2 label) in prose outside the\n93\t# matrix, while no matrix row carries the flag.\n94\tBUNDLE_ACK = re.compile(\n95\t    r'\\bbundl\\w*\\b[^.\\n]{0,100}\\b(?:P[012]\\b|HLR|priority)|'\n96\t    r'\\b(?:HLR|P[12]\\b|priority)[^.\\n]{0,100}\\bbundl\\w*\\b', re.I)\n97\t# An off-matrix bundling note that itself carries the why-not-splittable\n98\t# rationale is a compliant record; only a bare pointer is a violation.\n99\t# (\"same component/team\" is deliberately NOT a rationale marker — it restates\n100\t# the default boundary rule, not why the HLR is not separately schedulable.)\n101\tBUNDLE_RATIONALE = re.compile(\n102\t    r'\\b(?:because|since|shares?|shared|extends? the same|thin layer|'\n103\t    r'same (?:call|report|data|surface|file|ui|endpoint|code|site)|'\n104\t    r'not (?:independently|separately) (?:deferrable|schedulable)|'\n105\t    r'double-touch|two (?:epics|passes|audits)|'\n106\t    r'duplicat\\w+ the (?:audit|work|pass)|fragment\\w+)\\b', re.I)\n107\tMATRIX_ROW_BUNDLED = re.compile(r'^\\s*\\|.*\\bbundl', re.I | re.M)\n108\tMATRIX_RE = re.compile(r'#+\\s*HLR Traceability Matrix.*?(?=\\n#|\\Z)', re.S)\n109\t\n110\t\n111\tdef read_frontmatter(path):\n112\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n113\t    with open(path, encoding=\"utf-8\") as f:\n114\t        content = f.read()\n115\t    m = FRONTMATTER_RE.match(content)\n116\t    if not m:\n117\t        return {}, content\n118\t    try:\n119\t        data = yaml.safe_load(m.group(1))\n120\t    except yaml.YAMLError:\n121\t        return {}, content\n122\t    if not isinstance(data, dict):\n123\t        return {}, content\n124\t    return data, content[m.end():]\n125\t\n126\t\n127\tdef body_headings(body):\n128\t    heads = []\n129\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n130\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n131\t    return heads\n132\t\n133\t\n134\tdef load_epics(artifacts_dir, strat_id):\n135\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n136\t\n137\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n138\t    \"\"\"\n139\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n140\t    if not os.path.isdir(task_dir):\n141\t        return {}\n142\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n143\t    epics = {}\n144\t    for name in sorted(os.listdir(task_dir)):\n145\t        m = pat.match(name)\n146\t        if not m:\n147\t            continue\n148\t        path = os.path.join(task_dir, name)\n149\t        fm, body = read_frontmatter(path)\n150\t        epics[name[:-3]] = (path, fm, body)\n151\t    return epics\n152\t\n153\t\n154\tdef dependency_closure(start_key, deps):\n155\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n156\t    seen, stack = set(), list(deps.get(start_key, []))\n157\t    while stack:\n158\t        n = stack.pop()\n159\t        if n in seen or n not in deps:\n160\t            continue\n161\t        seen.add(n)\n162\t        stack.extend(deps[n])\n163\t    return seen\n164\t\n165\t\n166\tdef check(strat_id, artifacts_dir, components_path):\n167\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n168\t    probs = []\n169\t    epics = load_epics(artifacts_dir, strat_id)\n170\t    if not epics:\n171\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n172\t                % (strat_id, artifacts_dir)]\n173\t\n174\t    valid_components = set()\n175\t    if os.path.isfile(components_path):\n176\t        with open(components_path, encoding=\"utf-8\") as f:\n177\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n178\t    if not valid_components:\n179\t        probs.append(\"cannot read canonical component list %s — verify the \"\n180\t                     \"path before trusting component names\" % components_path)\n181\t\n182\t    deps, is_branch, is_docs, is_impl, itype, prio = {}, {}, {}, {}, {}, {}\n183\t    for key, (path, fm, body) in epics.items():\n184\t        name = key + \".md\"\n185\t        # 1. body sections (contract parity with the artifact judge)\n186\t        heads = body_headings(body)\n187\t        for want, aliases in SECTIONS:\n188\t            if not any(a in h for h in heads for a in aliases):\n189\t                probs.append(\"%s: body missing '%s' section (required \"\n190\t                             \"sections: Description, Scope, Acceptance \"\n191\t                             \"Criteria, HLR Traceability)\" % (name, want))\n192\t        # 2. component vocabulary\n193\t        comp = fm.get(\"component\")\n194\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n195\t                and comp.strip() not in valid_components:\n196\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n197\t                         \"canonical name (submit.py strips unknown names)\"\n198\t                         % (name, comp.strip(), components_path))\n199\t        # collect graph facts\n200\t        dl = fm.get(\"dependencies\")\n201\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n202\t            if isinstance(dl, list) else []\n203\t        is_branch[key] = \"BRANCH-\" in key\n204\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n205\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n206\t        it = fm.get(\"implementation_type\")\n207\t        itype[key] = it if it in IT_ENUM else None\n208\t        prio[key] = fm.get(\"priority\")\n209\t\n210\t    def kind(key):\n211\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n212\t        that is not type Implementation is never a parallel-rule party; an\n213\t        Implementation epic's kind is its implementation_type when that is a\n214\t        known label, else 'general'.\"\"\"\n215\t        if not is_impl[key]:\n216\t            return \"non-implementation\"\n217\t        return itype[key] or \"general\"\n218\t\n219\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n220\t    universe = [k for k in epics\n221\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n222\t    for k in sorted(epics):\n223\t        if not is_docs[k]:\n224\t            continue\n225\t        cl = dependency_closure(k, deps)\n226\t        missing = sorted(e for e in universe if e != k and e not in cl)\n227\t        if missing:\n228\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n229\t                         \"Implementation epic — add %s to its dependency chain\"\n230\t                         % (k, \", \".join(missing)))\n231\t\n232\t    # 4. Priority inheritance — enablers of P0 work must be P0\n233\t    for k in sorted(epics):\n234\t        if is_branch[k] or is_docs[k]:\n235\t            continue\n236\t        if prio.get(k) != \"P0\":\n237\t            continue\n238\t        # every main-plan, non-docs epic in k's closure enables P0 work\n239\t        cl = dependency_closure(k, deps)\n240\t        for t in sorted(cl):\n241\t            if is_branch[t] or is_docs[t]:\n242\t                continue\n243\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n244\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n245\t                             \"but is %s — raise it to P0 or restructure\"\n246\t                             % (t, prio.get(t), k, prio.get(t)))\n247\t\n248\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n249\t    #    pairs carry no dependencies edge in either direction (direct edges\n250\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n251\t    #    them; dependencies naming epics with no file cannot be judged).\n252\t    for k in sorted(epics):\n253\t        if kind(k) == \"docs-authoring\":\n254\t            continue\n255\t        for t in deps[k]:\n256\t            if t not in epics:\n257\t                continue\n258\t            pair = frozenset((kind(t), kind(k)))\n259\t            rule = PARALLEL_PAIRS.get(pair)\n260\t            if rule:\n261\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n262\t                             \"parallel; remove the dependencies edge and \"\n263\t                             \"express any coupling as an AC gate on the \"\n264\t                             \"dependent epic\"\n265\t                             % (rule, t, kind(t), k, kind(k)))\n266\t\n267\t    # 6. Epic-size overage triggers — a summary that acknowledges an epic kept\n268\t    #    above the ~2-week guideline must record a concrete re-split trigger.\n269\t    #    (Summary-side: overage text in epic bodies or reviews is out of scope;\n270\t    #    negated acknowledgments (\"stays within the guideline\") are clean.)\n271\t    summary_path = os.path.join(artifacts_dir, \"epic-tasks\",\n272\t                                strat_id + \"-decomposition.md\")\n273\t    if os.path.isfile(summary_path):\n274\t        with open(summary_path, encoding=\"utf-8\") as f:\n275\t            summary = f.read()\n276\t        acked = any(OVERAGE_ACK.search(seg) and not OVERAGE_NEG.search(seg)\n277\t                    for line in summary.splitlines()\n278\t                    for seg in re.split(r'(?<=\\.)\\s+', line))\n279\t        if acked and not RESPLIT_TRIG.search(summary):\n280\t            probs.append(\n281\t                \"summary acknowledges an epic kept above the size guideline \"\n282\t                \"with no re-split trigger — a bare overage note is an \"\n283\t                \"unresolved defect every later review will re-dock. FIX: \"\n284\t                \"append to that Health Warning a concrete planning condition, \"\n285\t                \"e.g. \\\"Re-split trigger: re-split <epic> if <the measurable \"\n286\t                \"condition that would make it more than one logical change, \"\n287\t                \"e.g. the audit/count estimate is exceeded>.\\\"\")\n288\t\n289\t        # 7. On-matrix bundling record — a bare-pointer bundling\n290\t        #    acknowledgment (no inline rationale, no matrix row flag) reads as\n291\t        #    an unanalyzed priority collapse; a self-contained note or a\n292\t        #    flagged row is a compliant record.\n293\t        mm = MATRIX_RE.search(summary)\n294\t        if mm:\n295\t            outside = summary[:mm.start()] + summary[mm.end():]\n296\t            lines = outside.splitlines()\n297\t            bare_pointer = False\n298\t            for i, line in enumerate(lines):\n299\t                if BUNDLE_ACK.search(line):\n300\t                    window = line + \" \" + (lines[i + 1] if i + 1 < len(lines)\n301\t                                           else \"\")\n302\t                    if not BUNDLE_RATIONALE.search(window):\n303\t                        bare_pointer = True\n304\t                        break\n305\t            if bare_pointer \\\n306\t                    and not MATRIX_ROW_BUNDLED.search(mm.group(0)):\n307\t                probs.append(\n308\t                    \"summary acknowledges a lower-priority HLR bundled into a \"\n309\t                    \"higher-priority epic, but the HLR Traceability Matrix row \"\n310\t                    \"carries no `bundled` flag — the rationale must be on the \"\n311\t                    \"record where the mapping is read. FIX: change that row's \"\n312\t                    \"Epic cell to \\\"<epic> (bundled)\\\" and append the rationale \"\n313\t                    \"to the row: \\\"Bundled with the P0 work: <why the HLR is \"\n314\t                    \"not separately schedulable — it edits the same call sites/\"\n315\t                    \"surface>; a split would double-touch the same files.\\\"\")\n316\t    return probs\n317\t\n318\t\n319\t# ─── self-check ───────────────────────────────────────────────────────────────\n320\t\n321\tdef _self_check():\n322\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n323\t    import shutil\n324\t    import tempfile\n325\t\n326\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n327\t    try:\n328\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n329\t        os.makedirs(art)\n330\t        comp = os.path.join(tmp, \"components.txt\")\n331\t        with open(comp, \"w\") as f:\n332\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n333\t\n334\t        def write(name, fm, body):\n335\t            with open(os.path.join(art, name), \"w\") as f:\n336\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n337\t\n338\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n339\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n340\t        write(\"RHAISTRAT-9001-E001.md\",\n341\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n342\t              \"dependencies: []\\n\", good_body)\n343\t        write(\"RHAISTRAT-9001-E002.md\",\n344\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n345\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n346\t              \"dependencies: [RHAISTRAT-9001-E001, RHAISTRAT-9001-E003]\\n\",\n347\t              good_body)\n348\t        # a konflux-onboarding epic parallel to the general epic (no edge\n349\t        # either way) is the Rule 10-compliant shape — must not be flagged\n350\t        write(\"RHAISTRAT-9001-E003.md\",\n351\t              \"component: Dashboard\\ntype: Implementation\\n\"\n352\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n353\t              \"dependencies: []\\n\", good_body)\n354\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n355\t                     comp) == [], \"good fixture must pass cleanly\"\n356\t\n357\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge,\n358\t        # Rule 10 konflux-onboarding -> general edge\n359\t        write(\"RHAISTRAT-9002-E001.md\",\n360\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n361\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n362\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n363\t              \"## HLR Traceability\\nh\\n\")\n364\t        write(\"RHAISTRAT-9002-E002.md\",\n365\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n366\t              \"dependencies: []\\n\", good_body)\n367\t        write(\"RHAISTRAT-9002-E003.md\",\n368\t              \"component: Dashboard\\ntype: Implementation\\n\"\n369\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n370\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n371\t        # E004 is a main-plan Implementation the docs epic never depends on\n372\t        write(\"RHAISTRAT-9002-E004.md\",\n373\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n374\t              \"dependencies: [RHAISTRAT-9002-E005]\\n\", good_body)\n375\t        write(\"RHAISTRAT-9002-E005.md\",\n376\t              \"component: Dashboard\\ntype: Implementation\\n\"\n377\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n378\t              \"dependencies: []\\n\", good_body)\n379\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n380\t        joined = \"\\n\".join(probs)\n381\t        assert \"missing 'Scope'\" in joined, probs\n382\t        assert \"Model Serving Stack\" in joined, probs\n383\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n384\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n385\t        r10 = [p for p in probs if p.startswith(\"Rule 10:\")]\n386\t        assert len(r10) == 1 and \"E005\" in r10[0] and \"E004\" in r10[0], probs\n387\t\n388\t        # checks 6/7 need a decomposition summary next to the epic files\n389\t        def write_summary(sid, body):\n390\t            with open(os.path.join(art, sid + \"-decomposition.md\"), \"w\") as f:\n391\t                f.write(\"---\\nparent_strat: %s\\n---\\n%s\" % (sid, body))\n392\t\n393\t        matrix = (\"## HLR Traceability Matrix\\n\\n\"\n394\t                  \"| HLR | Priority | Requirement | Epic |\\n\"\n395\t                  \"|-----|----------|-------------|------|\\n\"\n396\t                  \"| HLR-1 | P0 | core work | RHAISTRAT-9003-E001 |\\n\"\n397\t                  \"| HLR-2 | P1 | enhancement | RHAISTRAT